import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 998244353;
    static final int G = 3;

    static long fastPower(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static void bitSwap(long[] array, int length) {
        int j = 0;
        for (int i = 1; i < length; i++) {
            int bit = length >> 1;
            while (j >= bit) {
                j -= bit;
                bit >>= 1;
            }
            j += bit;
            if (i < j) {
                long temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
    }

    static void fftTransform(long[] array, int length, int direction) {
        bitSwap(array, length);
        for (int size = 2; size <= length; size <<= 1) {
            long wlen = fastPower(G, (MOD - 1) / size);
            if (direction == -1) wlen = fastPower(wlen, MOD - 2);
            for (int start = 0; start < length; start += size) {
                long w = 1;
                for (int k = start; k < start + size / 2; k++) {
                    long u = array[k];
                    long v = array[k + size / 2] * w % MOD;
                    array[k] = (u + v) % MOD;
                    array[k + size / 2] = (u - v + MOD) % MOD;
                    w = w * wlen % MOD;
                }
            }
        }
        if (direction == -1) {
            long invLen = fastPower(length, MOD - 2);
            for (int i = 0; i < length; i++) {
                array[i] = array[i] * invLen % MOD;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int len = 1;
        int halfN = n / 2;
        while (len < (9 * halfN + 1)) len <<= 1;
        long[] arr = new long[len];

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            arr[x] = 1;
        }

        fftTransform(arr, len, 1);

        for (int i = 0; i < len; i++) {
            if (arr[i] != 0) {
                arr[i] = fastPower(arr[i], halfN) % MOD;
            }
        }

        fftTransform(arr, len, -1);

        long total = 0;
        for (int i = 0; i < len; i++) {
            total = (total + arr[i] * arr[i]) % MOD;
        }

        System.out.println(total);
        sc.close();
    }
}
